evidenceRecords.command:
/usr/bin/bash -lc "node --test tests/public.test.mjs && node --input-type=module <<'EOF'
import {DatabaseSync} from 'node:sqlite';
import {createApi} from './src/api.ts';
const db=new DatabaseSync(':memory:');
db.exec(\"CREATE TABLE inventory(tenant_id TEXT NOT NULL,sku TEXT NOT NULL,stock INTEGER NOT NULL,unit_price_cents INTEGER NOT NULL,PRIMARY KEY(tenant_id,sku)); CREATE TABLE reservations(tenant_id TEXT NOT NULL,request_id TEXT NOT NULL,items_json TEXT NOT NULL,total_cents INTEGER NOT NULL,fee_cents INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(tenant_id,request_id));\");
db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('t','low',10,999); db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('t','high',10,1000);
const api=createApi(db); const low=await api.reserve({tenantId:'t',requestId:'low',items:[{sku:'low',quantity:1}]}); const high=await api.reserve({tenantId:'t',requestId:'high',items:[{sku:'high',quantity:10}]}); const retry=await api.reserve({tenantId:'t',requestId:'low',items:[{sku:'low',quantity:1}]}); if(low.feeCents"'!==25||high.feeCents!==0||retry.feeCents!==25) throw new Error('"'fee behavior failed'); console.log('focused fee/idempotency checks passed'); db.close();
EOF"

